'use strict';

// MODULES //

var fetchGitHubArtifact = require( '@data-apis/providers/github/fetch-artifact' );
var validateNeutralOrigin = require( '@data-apis/sources/validate-neutral-origin' );


// MAIN //

/**
* Fetches a CI artifact through a provider adapter.
*
* @param {Object} context - source context
* @returns {Promise<Object>} payload bytes and neutral origin
*/
async function fetchCiArtifact( context ) {
	var providers = context.providers || new Map( [
		['github', fetchGitHubArtifact]
	] );
	var adapter = providers.get( context.source.provider );
	var result;

	if ( !adapter ) {
		throw new Error( 'Unsupported CI provider: ' + context.source.provider );
	}
	result = await adapter( context );
	if ( !result || !Buffer.isBuffer( result.bytes ) ) {
		throw new Error( 'Provider adapter did not return payload bytes' );
	}
	validateNeutralOrigin( result.origin );
	return result;
}


// EXPORTS //

module.exports = fetchCiArtifact;
